// This code has been fully generated by an AI.

package analysis

import "math"

// Best efforts are computed from the per-record channels of an activity.
// Inputs are parallel slices: t holds seconds since the start, missing
// values in the float channels are NaN.

// Window is a section of an activity in seconds since its start.
type Window struct {
	StartS, EndS float64
}

// FastestDistance returns the shortest elapsed time needed for meters, or
// ok=false if the activity is shorter. The start of the window is
// interpolated between records, so the result does not depend on the
// recording interval. Elapsed time is used (stops count), as on Strava.
func FastestDistance(t []int64, dist []float64, meters float64) (seconds float64, w Window, ok bool) {
	ts, ds := validPairs(t, dist)
	if len(ds) < 2 || ds[len(ds)-1]-ds[0] < meters {
		return 0, Window{}, false
	}
	best := math.Inf(1)
	i := 0
	for j := 1; j < len(ds); j++ {
		for i+1 < j && ds[j]-ds[i+1] >= meters {
			i++
		}
		if ds[j]-ds[i] < meters {
			continue
		}
		// Exact start position lies between record i and i+1.
		start := ts[i]
		if span := ds[i+1] - ds[i]; span > 0 && i+1 <= j {
			frac := (ds[j] - meters - ds[i]) / span
			start = ts[i] + frac*(ts[i+1]-ts[i])
		}
		if d := ts[j] - start; d < best {
			best, w = d, Window{StartS: start, EndS: ts[j]}
		}
	}
	if math.IsInf(best, 1) {
		return 0, Window{}, false
	}
	return best, w, true
}

// validPairs returns time and a non-decreasing distance for records with a
// distance value (GPS dropouts can make the raw distance jump back).
func validPairs(t []int64, dist []float64) (ts, ds []float64) {
	last := math.Inf(-1)
	for k := range min(len(t), len(dist)) {
		d := dist[k]
		if math.IsNaN(d) {
			continue
		}
		d = math.Max(d, last)
		last = d
		ts = append(ts, float64(t[k]))
		ds = append(ds, d)
	}
	return ts, ds
}

// maxPowerHold is the longest gap between two records over which the last
// power value is held; longer gaps (auto pause) count as 0 W.
const maxPowerHold = 5

// PowerCurve returns the best average power for each duration in seconds
// (the "mean maximal power" curve). Records are resampled to one value per
// second; durations longer than the activity are missing from the result.
func PowerCurve(t []int64, power []float64, durations []int) map[int]PowerEffort {
	grid := powerGrid(t, power)
	if grid == nil {
		return nil
	}
	length := len(grid)
	prefix := make([]float64, length+1)
	for s, p := range grid {
		prefix[s+1] = prefix[s] + p
	}
	out := map[int]PowerEffort{}
	for _, d := range durations {
		if d <= 0 || d > length {
			continue
		}
		best, at := -1.0, 0
		for s := 0; s+d <= length; s++ {
			if sum := prefix[s+d] - prefix[s]; sum > best {
				best, at = sum, s
			}
		}
		if best > 0 {
			out[d] = PowerEffort{Watts: best / float64(d), Window: Window{StartS: float64(at), EndS: float64(at + d)}}
		}
	}
	return out
}

// powerGrid resamples power to one value per second; gaps longer than
// maxPowerHold count as 0 W. nil without any power value.
func powerGrid(t []int64, power []float64) []float64 {
	n := min(len(t), len(power))
	if n == 0 {
		return nil
	}
	t0 := t[0]
	length := int(t[n-1]-t0) + 1
	if length <= 0 || length > 7*24*3600 {
		return nil
	}
	grid := make([]float64, length)
	any := false
	for k := range n {
		p := power[k]
		if math.IsNaN(p) || p < 0 {
			continue
		}
		any = true
		from := int(t[k] - t0)
		to := from + 1
		if k+1 < n {
			to = min(int(t[k+1]-t0), from+maxPowerHold)
		}
		for s := from; s < to && s < length; s++ {
			grid[s] = p
		}
	}
	if !any {
		return nil
	}
	return grid
}

// PowerEffort is the best average power over one duration.
type PowerEffort struct {
	Watts float64
	Window
}

// Climb is a continuous ascent.
type Climb struct {
	GainM     float64
	DistanceM float64
	Window
}

// climbTolerance is the descent that ends a climb; smaller dips (and
// barometric noise) belong to the climb.
const climbTolerance = 10.0

// minClimbGain is the smallest net gain reported as climb.
const minClimbGain = 30.0

// LargestClimb returns the climb with the largest net elevation gain. A
// climb runs from a low point to the highest point before the altitude
// drops by more than climbTolerance.
func LargestClimb(t []int64, alt, dist []float64) (Climb, bool) {
	type point struct {
		t, alt, dist float64
	}
	var pts []point
	for k := range min(len(t), len(alt)) {
		if math.IsNaN(alt[k]) {
			continue
		}
		d := math.NaN()
		if k < len(dist) {
			d = dist[k]
		}
		pts = append(pts, point{float64(t[k]), alt[k], d})
	}
	if len(pts) < 2 {
		return Climb{}, false
	}
	var best Climb
	low, high := pts[0], pts[0]
	finish := func() {
		if gain := high.alt - low.alt; gain > best.GainM {
			best = Climb{GainM: gain, Window: Window{StartS: low.t, EndS: high.t}}
			if !math.IsNaN(high.dist) && !math.IsNaN(low.dist) {
				best.DistanceM = high.dist - low.dist
			}
		}
	}
	for _, p := range pts[1:] {
		switch {
		case p.alt >= high.alt:
			high = p
		case high.alt-p.alt > climbTolerance:
			finish()
			low, high = p, p
		}
		if p.alt < low.alt {
			low, high = p, p
		}
	}
	finish()
	if best.GainM < minClimbGain {
		return Climb{}, false
	}
	return best, true
}

// Split is a section of fixed distance, used when an activity has no laps.
type Split struct {
	Window
	DistanceM float64
	AscentM   float64
	DescentM  float64
	AvgHR     float64
	AvgPower  float64
}

// Splits cuts an activity into sections of every meters; the last section
// holds the rest if it is at least 10 % of meters long. Averages are over
// the records of a section (heart rate and power ignore missing values).
func Splits(t []int64, dist, alt, hr, power []float64, every float64) []Split {
	if every <= 0 {
		return nil
	}
	var out []Split
	var cur Split
	var hrSum, hrN, pSum, pN float64
	startD, lastAlt := math.NaN(), math.NaN()
	lastD := math.Inf(-1)
	flush := func(endT, endD float64) {
		cur.EndS, cur.DistanceM = endT, endD-startD
		if hrN > 0 {
			cur.AvgHR = hrSum / hrN
		}
		if pN > 0 {
			cur.AvgPower = pSum / pN
		}
		out = append(out, cur)
	}
	at := func(s []float64, k int) float64 {
		if k < len(s) {
			return s[k]
		}
		return math.NaN()
	}
	for k := range min(len(t), len(dist)) {
		d := dist[k]
		if math.IsNaN(d) {
			continue
		}
		d = math.Max(d, lastD)
		lastD = d
		tk := float64(t[k])
		if math.IsNaN(startD) {
			startD, cur = d, Split{Window: Window{StartS: tk}}
		}
		if a := at(alt, k); !math.IsNaN(a) {
			if !math.IsNaN(lastAlt) {
				if a > lastAlt {
					cur.AscentM += a - lastAlt
				} else {
					cur.DescentM += lastAlt - a
				}
			}
			lastAlt = a
		}
		if h := at(hr, k); !math.IsNaN(h) && h > 0 {
			hrSum, hrN = hrSum+h, hrN+1
		}
		if p := at(power, k); !math.IsNaN(p) {
			pSum, pN = pSum+p, pN+1
		}
		if d-startD >= every {
			flush(tk, d)
			startD, cur = d, Split{Window: Window{StartS: tk}}
			hrSum, hrN, pSum, pN = 0, 0, 0, 0
		}
	}
	if !math.IsNaN(startD) && lastD-startD >= every/10 {
		flush(float64(t[len(t)-1]), lastD)
	}
	return out
}
